LANGUAGES = ["en", "es", "fr", "de", "it", "pt", "ru", "ja", "zh", "ko", "ar", "hi", "tr", "nl", "pl", "sv"]

OUTPUT_DIR = os.path.join(os.path.dirname(__file__), "..", "flutter_app", "assets", "lang")


def main():
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    for lang in LANGUAGES:
        data: dict[str, str] = {}
        for key, translations in TRANSLATIONS.items():
            if lang in translations:
                data[key] = translations[lang]
        output_path = os.path.join(OUTPUT_DIR, f"{lang}.json")
        with open(output_path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        print(f"  OK  {lang}.json  ({len(data)} keys)")
    print(f"\nDone — {len(LANGUAGES)} files written to {OUTPUT_DIR}")


if __name__ == "__main__":
    main()
